    new_phone = to_e164(contact.phone) if needs_phone else null

    needs_company = (contact.company == null or contact.company == "") and contact.email != null and contact.email != ""
    domain = null
    company_name = null
    if needs_company {
        parts = text.split(contact.email, "@")
        domain = parts[1] if list.length(parts) >= 2 else null
        company_name = domain_to_company[domain] if domain != null and domain in domain_to_company else null
    }

    will_update_phone = needs_phone and new_phone != null and new_phone != contact.phone
    will_update_company = company_name != null

    updated = null
    if will_update_phone or will_update_company {
        updated = boundary retry 2 {
            return update_contact({
                id: contact.id,
                phone: new_phone if will_update_phone else null,
                company: company_name if will_update_company else null
            })
        } catch err {
            return fail("UPDATE_FAILED", err.code + ": " + err.message)
        }
    }

    return {
        phone_fixed: will_update_phone,
        company_filled: will_update_company
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}

